  update "budget".holds h set state = 'voided' where h.tenant = p_tenant and h.id = v_hold.id;
  insert into "budget".keys (tenant, kind, op, key, content, definition, result, at)
  values (p_tenant, 'reserve', 'void', v_key, 'null'::jsonb, '52eee15ce300c86e8b9c1e3dcca93908', 'done', v_now)
  on conflict do nothing;
  return ('done', null)::"budget".result;
end
$chobo$;

-- reserve.status: held, posted, voided or expired; null when there is no such hold. A hold past its
-- expiry is expired here even before expire() gives back what it held.
create or replace function "budget"."reserve_status"(p_tenant text, "p_request" text, "p_attempt" text)
returns text
language sql as $chobo$
  select case when h.state = 'held' and h.deadline <= clock_timestamp() then 'expired' else h.state end
    from "budget".holds h
   where h.tenant = p_tenant and h.id = "budget".chobo_id(array['transfer', 'budget', p_tenant, 'reserve', 'hold', "p_request", "p_attempt", '0'])
$chobo$;

-- the balance of dept_budget: posted, held in and held out; 0 for an account no call has named
create or replace function "budget"."balance_dept_budget"(p_tenant text, "p_dept" text)
returns "budget".balance
language sql as $chobo$
  select coalesce(
    (select row(a.posted, a.held_in, a.held_out)::"budget".balance
       from "budget".accounts a
      where a.tenant = p_tenant and a.id = "budget".chobo_id(array['account', 'budget', p_tenant, 'dept_budget', "p_dept"])),
    row(0, 0, 0)::"budget".balance)
$chobo$;

-- the balance of allocations: posted, held in and held out; 0 for an account no call has named
create or replace function "budget"."balance_allocations"(p_tenant text)
returns "budget".balance
language sql as $chobo$
  select coalesce(
    (select row(a.posted, a.held_in, a.held_out)::"budget".balance
       from "budget".accounts a
      where a.tenant = p_tenant and a.id = "budget".chobo_id(array['account', 'budget', p_tenant, 'allocations'])),
    row(0, 0, 0)::"budget".balance)
$chobo$;

-- the balance of payees: posted, held in and held out; 0 for an account no call has named
create or replace function "budget"."balance_payees"(p_tenant text)
returns "budget".balance
language sql as $chobo$
  select coalesce(
    (select row(a.posted, a.held_in, a.held_out)::"budget".balance
       from "budget".accounts a
      where a.tenant = p_tenant and a.id = "budget".chobo_id(array['account', 'budget', p_tenant, 'payees'])),
    row(0, 0, 0)::"budget".balance)
$chobo$;

-- expire(): gives back what the holds past their expiry held, and marks them expired. PostgreSQL
-- has no clock of its own: call it from pg_cron or a job of the caller's. It takes at most `p_max`
-- holds, skips the ones a call is working on, and answers how many it ended.
create or replace function "budget".expire(p_max integer default 1000)
returns integer
language plpgsql as $chobo$
declare
  v_now timestamptz := clock_timestamp();
  v_due "budget".holds[];
  v_hold "budget".holds;
  v_m jsonb;
  v_held bigint;
begin
  select array_agg(h order by h.tenant, h.id) into v_due
    from (select * from "budget".holds h
           where h.state = 'held' and h.deadline <= v_now
           order by h.deadline, h.tenant, h.id
           limit p_max
             for update skip locked) as h;
  if v_due is null then
    return 0;
  end if;
  -- their accounts, locked in the order of their IDs, as every call locks them
  perform 1 from "budget".accounts a
   where (a.tenant, a.id) in (select h.tenant, (m ->> e.side)::uuid
                                from unnest(v_due) as h, jsonb_array_elements(h.moves) as m, (values ('from'), ('to')) as e (side))
   order by a.tenant, a.id
     for update;
  foreach v_hold in array v_due loop
    for v_m in select x from jsonb_array_elements(v_hold.moves) as x loop
      v_held := (v_m ->> 'amount')::bigint;
      update "budget".accounts a set held_out = a.held_out - v_held
       where a.tenant = v_hold.tenant and a.id = (v_m ->> 'from')::uuid;
      update "budget".accounts a set held_in = a.held_in - v_held
       where a.tenant = v_hold.tenant and a.id = (v_m ->> 'to')::uuid;
      insert into "budget".entries (tenant, at, kind, op, key, account, d_posted, d_held_in, d_held_out) values
        (v_hold.tenant, v_now, v_hold.kind, 'expire', v_hold.key, (v_m ->> 'from')::uuid, 0, 0, -v_held),
        (v_hold.tenant, v_now, v_hold.kind, 'expire', v_hold.key, (v_m ->> 'to')::uuid, 0, -v_held, 0);
    end loop;
    update "budget".holds h set state = 'expired' where h.tenant = v_hold.tenant and h.id = v_hold.id;
  end loop;
  return cardinality(v_due);
end
$chobo$;
